import test_native_preflight_retry as base
FILES={'format':'htkk-web-native-output-publication-status-v1','status':'rejected','code':'FILES'}
def gtgt():
 return {'total_count':2,'jobs':[{'name':'readiness','id':1,'conclusion':'failure','steps':copy.deepcopy(STEPS)},{'name':'report_failure','conclusion':'success'}]},[copy.deepcopy(REPORT)]+copy.deepcopy(OTHER_RECORDS)
def declaration():
 jobs,records=gtgt();report=records[0];report['guiReferenceAutomationMode']=retry.DECLARATION_MODE
 for s in jobs['jobs'][0]['steps']:
  if s['name']==retry.RETAIN:s['conclusion']='skipped'
  if s['name']==retry.DECLARATION_RETAIN:s['conclusion']='success'
 return jobs,[x for x in records if x.get('format')!=FILES['format']]+[dict(retry.DECLARATION_NOT_STAGED)]
class StartupWindowRetry(unittest.TestCase):
 def test_real_run_is_one_pre_tax_startup_retry(self):
  self.assertEqual(retry.classify(*gtgt()),'startup-window-not-observed')
  self.assertEqual([x for x in OTHER_RECORDS if x.get('format')==FILES['format']],[FILES])
  self.assertEqual({s['name']for s in STEPS if s['conclusion']=='failure'},{retry.PROBE,retry.RETAIN})
  for k,v in (('startupWaitSeconds',45),('startupContext','only-hidden-app-windows'),('syntheticLogin',None),('guiReferenceAutomation',None),('taxDataUsed',False)):self.assertEqual(REPORT[k],v)
 def test_declaration_family_same_shape_retries(self):
  # Shape of run 42250602039 (declaration family, nothing staged, one hidden WinForms window).
  jobs,records=declaration();records[0]['ownedWindowKinds']={'winforms':1}
  self.assertEqual(retry.classify(jobs,records),'startup-window-not-observed')
  jobs,records=declaration();records.append(dict(FILES));self.assertIsNone(retry.classify(jobs,records))
 def test_longer_startup_limit_still_matches(self):
  jobs,records=gtgt();records[0].update(startupWaitSeconds=90,startupLimitSeconds=90,startupTimeline=[{'atSeconds':0,'processAlive':True,'appVisibleWindows':0,'appHiddenWindows':4}],startupTimelineTruncated=False)
  self.assertEqual(retry.classify(jobs,records),'startup-window-not-observed')
 def test_rejects_any_other_shape(self):
  report_mutations={
   'reason':{'blockedReason':'REGISTRATION_PROCESS_FAILED'},'exited':{'processAliveAfterWait':False},'window':{'windowObserved':True},
   'visible':{'appVisibleWindowCount':1},'context':{'startupContext':'no-app-windows-on-current-desktop'},'short-wait':{'startupWaitSeconds':30},
   'no-hidden':{'appHiddenWindowCount':0},'child':{'childProcessCount':1},'preexisting':{'preexistingHtkkProcessCount':1},'login-ready':{'loginReady':True},
   'uia':{'uiaStatus':'scanned'},'login':{'syntheticLogin':{'status':'next-window-not-yet-identified'}},'gui':{'guiReferenceAutomation':{'status':'timed-out'}},
   'tax':{'taxDataUsed':True},'roundtrip':{'runtimeRoundTrip':True},'host':{'referenceHostResult':{'status':'original-exited'}},'registration':{'registrationNonzeroExitCount':1},
   'registration-limit':{'registrationAcknowledgementLimitReached':True},'dialog-cue':{'nativeDialogCueCounts':{'error':1}},'owned':{'ownedWindowKinds':{'dialog':1}},
   'events':{'applicationEvents':{'matchedEventCount':1}},'werfault':{'descendantProcessKinds':dict(REPORT['descendantProcessKinds'],WerFault=1)},
   'evidence':{'privateWebNativeOutputEvidence':{}},'export':{'privateGtgtExportEvidence':{}},'diagnostic':{'privateSyntheticLoginDiagnostic':{}},
   'unmodified':{'originalSourcesUnmodified':False},'outbound':{'hostOutboundBlocked':False},'mode':{'guiReferenceAutomationMode':'gtgt-annex12-export-nonzero'},
   'missing-wait':{'startupWaitSeconds':None}}
  for name,update in report_mutations.items():
   jobs,records=gtgt();records[0].update(copy.deepcopy(update));self.assertIsNone(retry.classify(jobs,records),name)
  for name in ('boundary','permit','oracle','oracle-missing','publication','published','retain-step','evidence-step','login-step-extra-failure','declaration-status'):
   jobs,records=gtgt();r=records[0];steps=jobs['jobs'][0]['steps']
   if name=='boundary':r['supplierProcessBoundary']['cleanupVerified']=False
   if name=='permit':r['guiAutomationPermitBoundary']['authorizationAttempted']=True
   if name=='oracle':r['commonHeaderOracle']['status']='oracle-timeout'
   if name=='oracle-missing':del r['taxIdOracle']
   if name=='publication':records[:]=[x for x in records if x.get('format')!=FILES['format']]
   if name=='published':[x.update(status='published')for x in records if x.get('format')==FILES['format']]
   if name=='retain-step':[s.update(conclusion='success')for s in steps if s['name']==retry.RETAIN]
   if name=='evidence-step':next(s for s in steps if s['name'].startswith('Publish ')).update(conclusion='success')
   if name=='login-step-extra-failure':steps[0]['conclusion']='failure'
   if name=='declaration-status':records.append(dict(retry.DECLARATION_NOT_STAGED))
   self.assertIsNone(retry.classify(jobs,records),name)
 def test_recover_retries_only_attempt_one(self):
  f=base.NativePreflightRetry.fixture(base.NativePreflightRetry(),'startup');jobs,records=gtgt()
  f['steps'][:]=jobs['jobs'][0]['steps'];f['records'][:]=records
  self.assertTrue(f['recover']());self.assertEqual(len(f['calls']),2);self.assertIn('/rerun-failed-jobs',f['calls'][0][0])
  f=base.NativePreflightRetry.fixture(base.NativePreflightRetry(),'startup');f['steps'][:]=jobs['jobs'][0]['steps'];f['records'][:]=records
  f['run'].update(run_attempt=2);self.assertFalse(f['recover']());self.assertEqual(f['calls'],[])
 def test_probe_startup_wait_is_bounded_with_change_only_timeline(self):
  import pathlib;probe=(pathlib.Path(__file__).parent/'probe-htkk-windows.ps1').read_text(encoding='utf-8')
  self.assertIn('$startupLimitSeconds = 90',probe)
  self.assertIn('if ($report.rootAppWindowObserved -or $startupClock.Elapsed.TotalSeconds -ge $startupLimitSeconds) { break }',probe)
  self.assertIn('Start-Sleep -Seconds ([Math]::Min(2, [Math]::Max(1, [Math]::Ceiling($startupLimitSeconds - $startupClock.Elapsed.TotalSeconds))))',probe)
  self.assertIn('if ($startupSignature -cne $lastStartupSignature) { if ($startupTimeline.Count -lt 24) { $startupTimeline.Add($startupSample) } else { $report.startupTimelineTruncated = $true }; $lastStartupSignature = $startupSignature }',probe)
  self.assertNotIn('-ge 45) { break }',probe)
  self.assertGreaterEqual(90,retry.STARTUP_WAIT_FLOOR)
